<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?= esc($title ?? 'POS') ?></title>
<style>
:root{--ink:#172033;--muted:#667085;--brand:#635bff;--soft:#f4f6fb;--line:#e5e7eb;--danger:#b42318}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--soft);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{width:min(1080px,calc(100% - 32px));margin:0 auto}.topbar{background:#fff;border-bottom:1px solid var(--line)}.nav{display:flex;align-items:center;justify-content:space-between;gap:20px;min-height:72px}.brand{color:var(--ink);text-decoration:none;font-weight:800}.links{display:flex;gap:18px;flex-wrap:wrap}.links a{color:var(--muted);text-decoration:none}.links a:hover{color:var(--brand)}main{padding:46px 0 64px}.eyebrow{color:var(--brand);font-size:.78rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}h1{margin:8px 0 10px;font-size:clamp(2rem,5vw,3.4rem);letter-spacing:-.06em}h2{margin:0 0 8px}.lead{color:var(--muted);margin:0 0 26px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;box-shadow:0 8px 28px rgba(23,32,51,.05)}.actions{display:flex;gap:10px;align-items:center;justify-content:space-between;margin-bottom:18px}.button{display:inline-block;border:0;border-radius:9px;padding:10px 15px;background:var(--brand);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.button.secondary{background:#eef0ff;color:#4d46c4}.button.danger{background:#fff0ee;color:var(--danger)}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid var(--line);padding:14px 10px;text-align:left;white-space:nowrap}th{color:var(--muted);font-size:.78rem;letter-spacing:.08em;text-transform:uppercase}tr:last-child td{border-bottom:0}.avatar{height:48px;width:48px;border-radius:50%;object-fit:cover;vertical-align:middle}.form-grid{display:grid;gap:17px;max-width:650px}.field{display:grid;gap:7px}.field label{font-weight:700}.field input{border:1px solid #d0d5dd;border-radius:8px;padding:11px 12px;font:inherit}.field input:focus{outline:3px solid #e2e1ff;border-color:var(--brand)}.error{color:var(--danger);font-size:.9rem}.alert{border-radius:10px;padding:12px 15px;margin-bottom:18px;background:#ecfdf3;color:#027a48}.alert.error{background:#fff0ee;color:var(--danger)}.placeholder{display:inline-flex;align-items:center;justify-content:center;background:#e8eaff;color:#4d46c4;font-weight:800}.hero-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.hero-link{display:block;color:inherit;text-decoration:none}.hero-link:hover{border-color:var(--brand)}footer{color:var(--muted);text-align:center;padding:24px 0;font-size:.9rem}@media(max-width:650px){.nav{align-items:flex-start;flex-direction:column;padding:18px 0}.hero-grid{grid-template-columns:1fr}.actions{align-items:flex-start;flex-direction:column}}
</style></head><body><header class="topbar"><div class="shell nav"><a class="brand" href="<?= base_url('/') ?>">POS Management System</a><nav class="links"><a href="<?= base_url('customers') ?>">Customers</a><a href="<?= base_url('users') ?>">Users</a><a href="<?= base_url('about') ?>">About</a></nav></div></header><main class="shell">
